"""
Deep health check router.

Probes every external service that is configured via environment variables
and reports per-service reachability. The overall status is:
  - "ok"       all configured services responded
  - "degraded" some responded, some did not
  - "down"     none responded (or no services are configured)
"""

import asyncio
import os
from urllib.parse import urlparse

import httpx
from fastapi import APIRouter
from fastapi.responses import JSONResponse

router = APIRouter(prefix="/health", tags=["health"])

_PROBE_TIMEOUT = 5.0


def _base_url(raw: str) -> str:
    """Return scheme://host:port from a full URL (strips path)."""
    p = urlparse(raw)
    port_part = f":{p.port}" if p.port else ""
    return f"{p.scheme}://{p.hostname}{port_part}/"


async def _probe(url: str) -> str:
    """Return 'ok', 'timeout', or 'unreachable'."""
    try:
        async with httpx.AsyncClient(timeout=_PROBE_TIMEOUT) as client:
            await client.get(url)
        return "ok"
    except httpx.TimeoutException:
        return "timeout"
    except Exception:
        return "unreachable"


async def _collect_services() -> dict:
    """Discover configured external services and probe each one."""
    candidates: dict[str, str] = {}

    chat_url = os.getenv("CHAT_API_BASE_URL", "").strip()
    if chat_url:
        candidates["chat_api"] = chat_url.rstrip("/") + "/"

    openclaw_url = os.getenv("OPENCLAW_API_URL", "").strip()
    if openclaw_url:
        candidates["openclaw"] = _base_url(openclaw_url)

    hermes_url = os.getenv("HERMES_API_URL", "").strip()
    if hermes_url:
        candidates["hermes"] = _base_url(hermes_url)

    if not candidates:
        return {}

    results = await asyncio.gather(
        *[_probe(url) for url in candidates.values()],
        return_exceptions=True,
    )

    return {
        name: ("unreachable" if isinstance(result, Exception) else result)
        for (name, _), result in zip(candidates.items(), results)
    }


@router.get("/deep")
async def health_deep():
    """Probe all configured external services and return aggregate health."""
    services = await _collect_services()

    if not services:
        return JSONResponse(status_code=200, content={"status": "ok", "services": {}})

    ok_count = sum(1 for s in services.values() if s == "ok")
    total = len(services)

    if ok_count == total:
        overall, http_status = "ok", 200
    elif ok_count == 0:
        overall, http_status = "down", 503
    else:
        overall, http_status = "degraded", 207

    return JSONResponse(
        status_code=http_status,
        content={"status": overall, "services": services},
    )

